#include <zephyr/kernel.h>
#include <zephyr/drivers/adc.h>
#include <zephyr/sys/printk.h>

/* ADC device and channel defined in the devicetree.
 * Add a node in your board overlay like:
 *
 * / {
 *     zephyr,user {
 *         compatible = "zephyr,adc";
 *         io-channel = <&adc0 1>;   // example: ADC0, channel 1
 *         input = <&adc0>;
 *         reference = "VDD";
 *         acquisition-time = <ADC_ACQ_TIME(ADC_ACQ_TIME_MICROSECONDS, 10)>;
 *         resolution = <12>;
 *     };
 * };
 *
 * The code below accesses that node via DT_PATH(zephyr_user).
 */
static const struct adc_dt_spec adc_spec = ADC_DT_SPEC_GET(DT_PATH(zephyr_user));

void main(void)
{
    int ret;

    if (!device_is_ready(adc_spec.dev)) {
        printk("ADC device not ready\n");
        return;
    }

    ret = adc_channel_setup_dt(&adc_spec);
    if (ret) {
        printk("Failed to configure ADC channel (err %d)\n", ret);
        return;
    }

    while (true) {
        int16_t sample_buf[1];

        ret = adc_read_dt(&adc_spec, sample_buf);
        if (ret) {
            printk("ADC read error (err %d)\n", ret);
        } else {
            int32_t millivolts = 0;

            ret = adc_raw_to_millivolts_dt(&adc_spec,
                                           (int32_t)sample_buf[0],
                                           &millivolts);
            if (ret) {
                printk("Conversion to mV failed (err %d)\n", ret);
            } else {
                printk("ADC reading: %d mV\n", millivolts);
            }
        }

        k_sleep(K_MSLEEP(1000));
    }
}
